    "text": "지적측량 시행규칙상 경위의측량방법으로 세부측량을 할 때 측량대상\n토지의 경계점 간 실측거리가 15 m인 경우, 실측거리와 경계점\n좌표에 따라 계산한 거리의 교차는?",
